import { loadConfig } from "./core/config.ts";
import { newAgentState, runTurn } from "./core/agent.ts";
import { saveSession } from "./core/session.ts";
import { trace } from "./core/diagnostics.ts";
import { logger } from "./core/logger.ts";

/** One-shot mode: `glint -p "task"`. Prints the agent's progress to stdout. */
export async function runHeadless(prompt: string, yolo: boolean): Promise<void> {
  const config = loadConfig();
  if (yolo) config.yolo = true;
  const state = newAgentState();
  trace("session.start", { mode: "headless" });
  logger.info("headless.start", { prompt: prompt.slice(0, 200) });

  try {
    await runTurn(state, prompt, config.effort, {
      onAssistantText: (text) => process.stdout.write(text + "\n"),
      onToolStart: (tool, args) => {
        const hint =
          typeof args.command === "string"
            ? args.command
            : typeof args.path === "string"
              ? args.path
              : typeof args.pattern === "string"
                ? args.pattern
                : typeof args.task === "string"
                  ? args.task.slice(0, 80)
                  : "";
        process.stderr.write(`  ⏺ ${tool}${hint ? ` ${hint}` : ""}\n`);
      },
      onToolEnd: (tool, status, output) => {
        if (status === "error") process.stderr.write(`  ✗ ${tool}: ${output.slice(0, 200)}\n`);
      },
      onApproval: async (req) => {
        if (config.yolo) return true;
        process.stderr.write(`  ⚠ auto-denied (needs approval, run with --yolo): ${req.summary}\n`);
        return false;
      },
      onNotice: (text) => process.stderr.write(`  ! ${text}\n`),
    });
  } finally {
    saveSession(state, prompt);
    trace("session.end", { mode: "headless", usage: state.totalUsage });
  }
}

